cd /private/var/folders/7d/j58hwvpd4t3csmchy9y9kq600000gn/T/t01-ws-zmctlwyq/ws-04; python3 - <<'EOF'
p='service/mes_webhook.py'
s=open(p).read()
old=s[s.index('        raw = self.rfile.read'):s.index('        RECEIVED.append(event)')]
new='''        raw = self.rfile.read(int(self.headers.get("Content-Length", 0)))

        # Authenticate first, over the body bytes exactly as sent (per vendor docs).
        # Never re-serialise before verifying: json.dumps() escapes non-ASCII text
        # (e.g. operator "Müller") and changes the bytes, breaking the HMAC.
        ts = self.headers.get("X-MES-Timestamp", "")
        sig = self.headers.get("X-MES-Signature", "")
        try:
            skew = abs(time.time() - float(ts))
        except ValueError:
            return self._reply(401, {"error": "bad timestamp"})
        if skew > TOLERANCE_S:
            log.error("stale webhook skew=%.0fs", skew)
            return self._reply(401, {"error": "stale"})
        if not hmac.compare_digest(sig.encode(), expected_signature(ts, raw).encode()):
            log.error("signature mismatch skew=%.1fs", skew)
            return self._reply(401, {"error": "bad signature"})

        try:
            event = parse_event(raw)
        except ValueError as exc:
            log.warning("bad payload: %s", exc)
            return self._reply(400, {"error": "bad payload"})
        if skew > 1:
            log.warning("clock skew %.1fs plant=%s", skew, event.get("plant"))

'''
s=s.replace(old,new)
open(p,'w').write(s)
EOF
(python3 -m service.mes_webhook >/dev/null 2>&1 &) ; sleep 1
for op in "J. Becker" "Müller" "Nguyễn Văn An" "Łukasz"; do python3 tools/send_test_event.py "$op"; done
# tamper / bad sig check
curl -s -o /dev/null -w "%{http_code}\n" -X POST localhost:8081/webhooks/mes -H "X-MES-Timestamp: $(date +%s)" -H "X-MES-Signature: sha256=00" -d '{"event_id":"x","type":"y"}'
pkill -f service.mes_webhook

